"""Render a self-contained native-sample browser, explicitly not a parity report."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__)
p.add_argument('input',type=Path);p.add_argument('output',type=Path)
a=p.parse_args();data=json.loads(a.input.read_text())
for sample in data['samples']:sample.pop('events',None)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>JEWEL C++ · event sample browser</title>
<style>body{font:16px system-ui;background:#f4f6f8;color:#183042;margin:0}main{max-width:1080px;margin:40px auto;padding:0 24px}h1{font-size:32px;margin-bottom:8px}.note{background:#fff2d3;border-left:4px solid #bb7a00;padding:18px;line-height:1.5}.panel{background:white;padding:24px;margin:20px 0;border-radius:12px}label{display:inline-block;margin:0 22px 12px 0}select,button{font:inherit;padding:8px;border:1px solid #b9c6cf;border-radius:6px;background:white}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #dce3e8}svg{width:100%;height:auto}.small{font-size:14px;color:#466071}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}caption{text-align:left;font-weight:bold;margin-bottom:8px}</style>
<main><h1>JEWEL event samples</h1><p>Jet and substructure analysis through hepyy/cppyy FastJet</p>
<p class="note"><strong>Development evidence, not completed physics validation.</strong> These plots do not establish matched generator settings. Fortran/native ratios and the requested ±10% comparison have not been evaluated here. Native and imported Fortran samples may have different ISR/MPI and normalization policies. Recoil inclusion follows the selected run setting. Thermal subtraction follows the selected run setting; its policy is recorded below.</p>
<section class="panel"><label>Setting <select id="setting"></select></label><label>Observable <select id="observable"><option value="pt">Jet pT [GeV]</option><option value="girth">Girth</option><option value="ptd">pTD</option><option value="mass">Jet mass [GeV]</option><option value="groomed_mass">Soft Drop mass [GeV]</option><option value="zg">Soft Drop zg</option></select></label><button id="download">Download plotted CSV</button><p id="counts"></p><svg id="chart" viewBox="0 0 960 340" role="img" aria-label="Selected jet distribution"></svg><p class="small">Bars show weighted jets per denominator record in each bin (not divided by bin width). Native failed attempts contribute zero jets; imported Fortran denominators count written events only. Error bars are event-level standard errors.</p><table><caption id="caption"></caption><thead><tr><th>Bin</th><th>Weighted jets</th><th>Jets / record</th><th>Standard error</th></tr></thead><tbody id="rows"></tbody></table></section>
<section class="panel"><h2>Failures and selection</h2><pre id="failures"></pre><pre id="selection"></pre></section><details class="panel"><summary>Run settings and provenance</summary><pre id="provenance"></pre></details></main>
<script>const data=__DATA__;
const setting=document.getElementById('setting'), observable=document.getElementById('observable');
data.samples.forEach((s,i)=>{const option=document.createElement('option');option.value=i;option.textContent=`${s.run.generator_family||'Native C++'} · ${s.run.mode} · recoils ${s.run.keep_recoils===false?'excluded':'included'} · ${s.run.output_policy?'reference output (see cards)':s.run.subtraction?'subtracted R='+s.run.subtraction.radius+' · projection '+(s.run.subtraction.put_on_shell||0):'unsubtracted'}`;setting.appendChild(option)});
const ns='http://www.w3.org/2000/svg';function element(name,attrs,text){const e=document.createElementNS(ns,name);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;return e}
function current(){return data.samples[Number(setting.value)]}function fmt(v){return v===null?'—':Number(v).toPrecision(5)}
function render(){const s=current();Array.from(observable.options).forEach(o=>o.disabled=!(o.value in s.distributions));if(!(observable.value in s.distributions))observable.value='pt';const bins=s.distributions[observable.value], chart=document.getElementById('chart');chart.replaceChildren();
 const maximum=Math.max(...bins.map(b=>b.jets_per_attempt+(b.event_standard_error||0)),1e-12)*1.12;
 const x0=75,y0=280,width=855,height=235,step=width/bins.length;
 for(let i=0;i<=4;i++){const value=maximum*i/4,y=y0-height*i/4;chart.appendChild(element('line',{x1:x0,y1:y,x2:x0+width,y2:y,stroke:'#dde5eb'}));chart.appendChild(element('text',{x:65,y:y+4,'text-anchor':'end','font-size':12},fmt(value)))}
 bins.forEach((b,i)=>{const x=x0+i*step+8,y=y0-height*b.jets_per_attempt/maximum;const bar=element('rect',{x,y,width:Math.max(1,step-16),height:y0-y,fill:s.run.mode==='vacuum'?'#176d89':'#b16b22'});bar.appendChild(element('title',{},`${b.low}–${b.high}: ${fmt(b.jets_per_attempt)} ± ${fmt(b.event_standard_error)}`));chart.appendChild(bar);
 const centre=x0+(i+.5)*step,err=height*(b.event_standard_error||0)/maximum;chart.appendChild(element('line',{x1:centre,y1:y-err,x2:centre,y2:y+err,stroke:'#183042'}));chart.appendChild(element('text',{x:centre,y:302,'text-anchor':'middle','font-size':11},`${b.low}–${Number(b.high.toPrecision(4))}`));});
 document.getElementById('counts').textContent=`${s.summary.accepted} accepted / ${s.summary.attempts} denominator records (${s.denominator_scope||'attempted-events'}) · ${s.selected_jets} selected jets · ${s.summary.failed_attempts_known===false?'internal failures unknown':(s.summary.evolution_failures+s.summary.generation_failures)+' failed attempts'}`;
 document.getElementById('caption').textContent=observable.selectedOptions[0].textContent;
 const rows=document.getElementById('rows');rows.replaceChildren();bins.forEach(b=>{const tr=document.createElement('tr');[`${b.low}–${b.high}`,b.weighted_count,fmt(b.jets_per_attempt),fmt(b.event_standard_error)].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.appendChild(td)});rows.appendChild(tr)});
 document.getElementById('failures').textContent=JSON.stringify({failure_reasons:s.failure_reasons,observable_accounting:s.observable_accounting||'not recorded in this historical sample'},null,2);document.getElementById('selection').textContent=JSON.stringify({...data.selection,recoils:s.run.keep_recoils===false?'excluded during generation':'included',subtraction:s.run.output_policy||s.run.subtraction||'none'},null,2);document.getElementById('provenance').textContent=JSON.stringify({run:s.run,input:s.input,input_sha256:s.input_sha256,generator:data.generator,analysis:data.analysis_versions},null,2);}
setting.addEventListener('change',render);observable.addEventListener('change',render);document.getElementById('download').addEventListener('click',()=>{const s=current();const csv='low,high,weighted_count,jets_per_attempt,event_standard_error\\n'+s.distributions[observable.value].map(b=>[b.low,b.high,b.weighted_count,b.jets_per_attempt,b.event_standard_error].join(',')).join('\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const link=document.createElement('a');link.href=url;link.download=`${s.run.mode}-${observable.value}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});render();</script></html>'''
a.output.write_text(html.replace('__DATA__',json.dumps(data,allow_nan=False).replace('<','\\u003c')))
print(a.output)
